import{_ as a,c as t,o as i,ag as o}from"./chunks/framework.DZ_cNctr.js";const u=JSON.parse('{"title":"Sharing Views","description":"Share your exact view of a remote dataset with a URL. Zoom, position and channel settings travel in the link, and the recipient needs no install, download or account.","frontmatter":{"title":"Sharing Views","description":"Share your exact view of a remote dataset with a URL. Zoom, position and channel settings travel in the link, and the recipient needs no install, download or account."},"headers":[],"relativePath":"guides/sharing.md","filePath":"guides/sharing.md"}'),n={name:"guides/sharing.md"};function r(s,e,l,h,c,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="sharing-views" tabindex="-1">Sharing Views <a class="header-anchor" href="#sharing-views" aria-label="Permalink to &quot;Sharing Views&quot;">​</a></h1><p>Share your exact view of a remote dataset with anyone using a URL.</p><div class="tip custom-block"><p class="custom-block-title">What this replaces</p><p><a href="https://www.find-nuclei.com/blog/share-zarr-with-your-team" target="_blank" rel="noreferrer">Share Your Microscopy Data With Your Team Without Sending Anyone a Hard Drive</a> covers the alternatives a link saves you from: zipping the folder and uploading it somewhere, copying it to a shared drive and hoping the other side has the right software, or exporting a video and losing half the information.</p></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When you&#39;re viewing a remote (URL-based) dataset, the viewer encodes your current view state into the browser URL. This includes:</p><ul><li><strong>Dataset URL</strong>: which OME-ZARR to load</li><li><strong>Zoom level and position</strong>: where you&#39;re looking</li><li><strong>Channel settings</strong>: which channels are visible, their colors, and contrast ranges</li></ul><h2 id="copying-a-shareable-link" tabindex="-1">Copying a Shareable Link <a class="header-anchor" href="#copying-a-shareable-link" aria-label="Permalink to &quot;Copying a Shareable Link&quot;">​</a></h2><ol><li>Navigate to the region of interest</li><li>Adjust channels, colors, and contrast to highlight what matters</li><li>Click the <strong>🔗 Link</strong> button in the toolbar</li><li>A toast confirms: &quot;Link copied to clipboard&quot;</li><li>Paste the URL anywhere: email, Slack, a paper</li></ol><h2 id="what-the-recipient-sees" tabindex="-1">What the Recipient Sees <a class="header-anchor" href="#what-the-recipient-sees" aria-label="Permalink to &quot;What the Recipient Sees&quot;">​</a></h2><p>When someone opens your link:</p><ul><li>The viewer loads automatically (no install needed)</li><li>The same dataset streams from the same server</li><li>The view opens at your exact zoom and position</li><li>Channel settings match what you shared</li></ul><p>No account, no download, no setup. Just a URL.</p><div class="tip custom-block"><p class="custom-block-title">Local Data</p><p>Link sharing only works with remote (URL-based) datasets. For local files, the data lives on your machine and can&#39;t be referenced by URL.</p></div>',13)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
